CREATE OR REPLACE PACKAGE billing.charges AS
  TYPE t_account IS RECORD (
    id NUMBER,
    balance NUMBER
  );
  TYPE t_transfer IS RECORD (
    from_id NUMBER,
    to_id NUMBER,
    amt NUMBER
  );
  PROCEDURE transfer(p_args IN t_transfer);
END charges;
/

CREATE OR REPLACE PACKAGE BODY billing.charges AS

  PROCEDURE transfer(p_args IN t_transfer) IS
    l_src t_account;
  BEGIN
    DECLARE
      l_committed_0 BOOLEAN := FALSE;
    BEGIN
      SAVEPOINT pell_sp_0;  -- @ 03_transfer.pell:23
      BEGIN
        select id, balance
      INTO l_src
      FROM accounts where id = l_from_id and frozen = 0;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN RAISE;
        WHEN TOO_MANY_ROWS THEN RAISE;
      END;
      IF (l_src.balance < p_args.amt) THEN
        pell_runtime.set_err('billing_charges_overdraft:1', JSON_OBJECT('account' VALUE p_args.from_id, 'requested' VALUE p_args.amt, 'available' VALUE l_src.balance));
        RAISE pell_runtime.billing_charges_overdraft;
      END IF;
      update accounts set balance = balance - l_amt where id = l_from_id;
      update accounts set balance = balance + l_amt where id = l_to_id;
      COMMIT;
      l_committed_0 := TRUE;
    EXCEPTION
      WHEN OTHERS THEN
        IF NOT l_committed_0 THEN ROLLBACK TO pell_sp_0;  -- @ 03_transfer.pell:23 END IF;
        RAISE;
    END;
    RETURN;
  END transfer;
END charges;
/